CREATE OR REPLACE FUNCTION public.enforce_lead_status_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NOT public.is_valid_lead_status_transition(OLD.lead_status, NEW.lead_status) THEN
    RAISE EXCEPTION 'Invalid lead status transition: % -> %', OLD.lead_status, NEW.lead_status;
  END IF;

  IF NEW.lead_status IS DISTINCT FROM OLD.lead_status THEN
    NEW.status_updated_at = now();
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_activity_ticket_code()
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  code TEXT;
  chars TEXT := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  exists_check BOOLEAN;
BEGIN
  LOOP
    code := 'DALC-';
    FOR i IN 1..8 LOOP
      code := code || substr(chars, floor(random() * length(chars) + 1)::int, 1);
      IF i = 4 THEN code := code || '-'; END IF;
    END LOOP;
    SELECT EXISTS(SELECT 1 FROM public.activity_bookings WHERE ticket_code = code) INTO exists_check;
    EXIT WHEN NOT exists_check;
  END LOOP;
  RETURN code;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_experience_ticket_code()
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  code TEXT;
  exists_check BOOLEAN;
BEGIN
  LOOP
    -- Generate random 8 character code
    code := 'DALC-' || upper(substring(md5(random()::text) from 1 for 4)) || '-' || upper(substring(md5(random()::text) from 1 for 4));
    
    -- Check if code already exists
    SELECT EXISTS(SELECT 1 FROM public.experience_bookings WHERE ticket_code = code) INTO exists_check;
    
    EXIT WHEN NOT exists_check;
  END LOOP;
  
  RETURN code;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_venue_slug(input_name text, input_id text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  base_slug  TEXT;
  final_slug TEXT;
  counter    INTEGER := 0;
BEGIN
  base_slug := LOWER(
    REGEXP_REPLACE(
      REGEXP_REPLACE(
        REGEXP_REPLACE(input_name, '[^a-zA-Z0-9\s\-]', '', 'g'),
        '\s+', '-', 'g'
      ),
      '-{2,}', '-', 'g'
    )
  );
  base_slug := TRIM(BOTH '-' FROM base_slug);

  final_slug := base_slug;

  -- Ensure uniqueness by appending counter if slug already exists
  WHILE EXISTS (
    SELECT 1 FROM public.venues
    WHERE slug = final_slug AND id != input_id
  ) LOOP
    counter := counter + 1;
    final_slug := base_slug || '-' || counter;
  END LOOP;

  RETURN final_slug;
END;
$function$

