CREATE OR REPLACE FUNCTION public.venues_before_insert_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    NEW.slug := public.generate_venue_slug(NEW.name, NEW.id);
  END IF;
  RETURN NEW;
END;
$function$
